def normalize_existing_emails(apps, schema_editor):
    User = apps.get_model('users', 'User')
    users = User.objects.using(schema_editor.connection.alias)
    seen = {}
    updates = []
    # Revisar todos los correos antes de modificar cualquier registro.
    for pk, email in users.values_list('pk', 'email').iterator():
        normalized = (email or '').strip().lower()
        if not normalized:
            raise RuntimeError(f'El usuario {pk} no tiene correo. Corrígelo antes de migrar.')
        if normalized in seen:
            raise RuntimeError(
                f'Los usuarios {seen[normalized]} y {pk} tienen el mismo correo '
                'al ignorar mayúsculas. Resuelve el duplicado antes de migrar.'
            )
        seen[normalized] = pk
        if email != normalized:
            updates.append((pk, normalized))
    for pk, email in updates:
        users.filter(pk=pk).update(email=email)


